<?php
namespace Tests\Feature;use App\Models\User;use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class RegistrationOnboardingTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}public function test_registration_page_is_public():void{$this->get('/register')->assertOk()->assertSee('Create a SignalGrid account');}public function test_new_user_registers_as_viewer_and_enters_onboarding():void{$this->post('/register',['name'=>'New Research User','email'=>'new.user@example.test','password'=>'StrongPass!2026','password_confirmation'=>'StrongPass!2026','terms'=>1])->assertRedirect('/onboarding');$user=User::where('email','new.user@example.test')->firstOrFail();$this->assertTrue($user->hasRole('Viewer'));$this->assertAuthenticatedAs($user);}public function test_onboarding_completes_and_redirects_to_dashboard():void{$user=User::factory()->create();$user->assignRole('Viewer');$this->actingAs($user)->post('/onboarding',['department'=>'Computer Science','phone'=>'08000000000','intended_use'=>'academic_research'])->assertRedirect('/dashboard');$this->assertNotNull($user->fresh()->onboarding_completed_at);}public function test_duplicate_email_is_rejected():void{$user=User::factory()->create();$this->from('/register')->post('/register',['name'=>'Duplicate','email'=>$user->email,'password'=>'StrongPass!2026','password_confirmation'=>'StrongPass!2026','terms'=>1])->assertRedirect('/register')->assertSessionHasErrors('email');}}
